# Scans this folder (and assets/images/photos/pics) and rewrites images-list.js
# Only file paths are written (ASCII only), so there are no encoding problems.
# Titles and messages are generated by index.html.
$scriptDir = Split-Path -Parent $MyInvocation.MyCommand.Path
if (-not $scriptDir) { $scriptDir = (Get-Location).Path }

$extensions = @(".jpg", ".jpeg", ".png", ".gif", ".webp", ".bmp", ".svg", ".avif")
$imageFiles = @(Get-ChildItem -Path $scriptDir -File | Where-Object { $extensions -contains $_.Extension.ToLower() })

foreach ($sub in @("assets", "images", "photos", "pics")) {
    $subPath = Join-Path $scriptDir $sub
    if (Test-Path $subPath) {
        $imageFiles += @(Get-ChildItem -Path $subPath -File | Where-Object { $extensions -contains $_.Extension.ToLower() })
    }
}

$items = @()
foreach ($file in $imageFiles) {
    $relPath = $file.FullName.Substring($scriptDir.Length).TrimStart("\", "/") -replace "\\", "/"
    $escaped = $relPath -replace '"', '\"'
    $items += "  { src: `"$escaped`" }"
}

$jsContent = @"
// =========================================================================
// Birthday Gallery Images List
// Only the file paths are listed here. Beautiful titles and messages are
// added automatically by the website, so file names are never shown.
// To add photos: drop them in this folder (or assets/) and run update-images.bat
// =========================================================================

window.GALLERY_IMAGES = [
$($items -join ",`n")
];
"@

$outputPath = Join-Path $scriptDir "images-list.js"
$utf8NoBom = New-Object System.Text.UTF8Encoding $false
[System.IO.File]::WriteAllText($outputPath, $jsContent, $utf8NoBom)
Write-Host "Successfully updated images-list.js with $($imageFiles.Count) images!" -ForegroundColor Green
